package com.dokor.argos.services.analytics;
import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ProductMetricsTest {
@Test void separatesImmatureCohortsAndExcludesInvalidTimestamps(){var start=Instant.parse("2026-10-01T00:00:00Z");var rows=List.of(new ProductAnalyticsDao.CohortRow("/","fr","form","COMPLETED",start,start.plusSeconds(2),start.plusSeconds(12),true),new ProductAnalyticsDao.CohortRow("/","fr","form","QUEUED",start,null,null,false),new ProductAnalyticsDao.CohortRow("/","en","form","COMPLETED",start,start.minusSeconds(1),start.minusSeconds(2),false));var result=ProductMetrics.summarize(new ProductAnalyticsDao.Sample(rows,List.of(),false),start,start.plusSeconds(60),7,true);assertEquals(3,result.cohort().accepted());assertEquals(2,result.cohort().completed());assertEquals(1,result.cohort().pending());assertEquals(1,result.cohort().completedViewed());assertEquals(1,result.queue().sample());assertEquals(2,result.queue().excluded());assertEquals(2000L,result.queue().medianMs());assertEquals(10000L,result.processing().p95Ms());assertEquals(1,result.endToEnd().excluded());assertEquals(2,result.bySource().size());}
@Test void emptySamplesDoNotInventPercentiles(){var now=Instant.now();var result=ProductMetrics.summarize(new ProductAnalyticsDao.Sample(List.of(),List.of(),true),now,now,30,false);assertNull(result.queue().medianMs());assertTrue(result.capped());assertFalse(result.enabled());}
@Test void rejectsUnboundedDimensions(){assertThrows(IllegalArgumentException.class,()->new AnalyticsDimensions("/report/private","fr","page"));assertThrows(IllegalArgumentException.class,()->new AnalyticsDimensions("/","email@example.com","page"));}
}